<script>
const $=s=>document.querySelector(s);
const $$=s=>document.querySelectorAll(s);
const state={
  conversations:[],
  currentId:null,
  settings:{web:true,selection:false},
  live:null,
  stopFlag:false
};
const storage={
  load(){
    try{
      const c=localStorage.getItem("conversations");
      const s=localStorage.getItem("settings");
      state.conversations=c?JSON.parse(c):[];
      state.settings=s?JSON.parse(s):{web:true,selection:false};
    }catch(e){state.conversations=[];state.settings={web:true,selection:false}}
  },
  save(){localStorage.setItem("conversations",JSON.stringify(state.conversations))},
  saveSettings(){localStorage.setItem("settings",JSON.stringify(state.settings))}
};
function uid(){return "c_"+Date.now()+"_"+Math.random().toString(36).slice(2,8)}
function fmtDate(ts){const d=new Date(ts);return d.toLocaleString("hu-HU",{hour12:false})}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),1800)}
function init(){
  storage.load();
  renderSidebar();
  if(!state.conversations.length) newConversation();
  else {loadConversation(state.conversations[0].id)}
  $("#toggleWeb").classList.toggle("on",!!state.settings.web);
  document.body.classList.toggle("sel-enabled",!!state.settings.selection);
}
function newConversation(){
  const id=uid();
  const conv={id,title:"Új beszélgetés",created:Date.now(),updated:Date.now(),messages:[]};
  state.conversations.unshift(conv);
  state.currentId=id;
  storage.save();
  renderSidebar();
  renderMessages();
}
function loadConversation(id){
  state.currentId=id;
  renderSidebar();
  renderMessages();
}
function currentConv(){
  return state.conversations.find(c=>c.id===state.currentId)
}
