function extractKeywords(text){
  const words=(text||"").toLowerCase().replace(/[^a-záéíóöőúüű0-9\s]/gi," ").split(/\s+/).filter(Boolean);
  const stop=new Set(["és","vagy","hogy","a","az","egy","mint","mert","van","vannak","lenne","lesz","mi","mit","hogyan","mikor","hol","kell","nem","de","is","ha","akkor","azt","arra","erről","ez","ezek","arra","arrai","összehasonlítás","stb","a","the","of","in","to","for","on","with","by","from","at","as","is","are"]);
  const freq={};
  for(const w of words){if(stop.has(w)) continue;freq[w]=(freq[w]||0)+1}
