  const j=await r.json();
  const results=[];
  if(j.AbstractText) results.push({title:j.Heading||"Összefoglaló",url:j.AbstractURL||"",text:j.AbstractText});
  if(Array.isArray(j.RelatedTopics)){
    for(const t of j.RelatedTopics){
      if(t.Text && t.FirstURL) results.push({title:t.Text.split(" - ")[0],url:t.FirstURL,text:t.Text});
      if(Array.isArray(t.Topics)){
        for(const k of t.Topics){
          if(k.Text && k.FirstURL) results.push({title:k.Text.split(" - ")[0],url:k.FirstURL,text:k.Text});
        }
      }
      if(results.length>12) break;
    }
  }
  return results.slice(0,8);
}
