function drawBars(canvas,data){
  const ctx=canvas.getContext("2d");
  const W=canvas.width,H=canvas.height;
  ctx.clearRect(0,0,W,H);
  const pad=40;
  const max=Math.max(...data.map(d=>d.value),10);
  const bw=(W-pad*2)/(data.length*1.6);
  const gap=bw*0.6;
  ctx.fillStyle="#9fb1c8";
  ctx.font="12px system-ui, sans-serif";
  ctx.strokeStyle="#1d2733";
  ctx.lineWidth=1;
  ctx.beginPath();
  for(let i=0;i<=4;i++){
    const y=pad+((H-pad*2)*i/4);
    ctx.moveTo(pad,y);ctx.lineTo(W-pad,y);
  }
  ctx.stroke();
  data.forEach((d,i)=>{
    const x=pad+i*(bw+gap);
    const h=((H-pad*2)*d.value)/max;
    const y=H-pad-h;
    const g=ctx.createLinearGradient(0,y,0,y+h);
    g.addColorStop(0,"#2196f3");
    g.addColorStop(1,"#1565c0");
    ctx.fillStyle=g;
    ctx.fillRect(x,y,bw,h);
    ctx.fillStyle="#cfe7ff";
    ctx.fillText(String(d.label).slice(0,12),x, H-pad+14);
    ctx.fillStyle="#82b1ff";
    ctx.fillText(d.value.toString(),x, y-6);
  });
}
